		INSERT /* SQL_ID: RdfTripleLogMapper.insertRdfTripleLog */
		       INTO dtmeta.tb_rdf_triplelog
			 ( rdf_triple_log_id
             , log_dt
             , sbjt_ri
             , predct_ri
             , objt_ri
             , log_div_mtcd
             , log_store_lo_nm
             , log_regr_id
			 ) VALUES 
			 ( 
			   #{rdfTripleLogId}			 			 
			 , current_timestamp
			 , #{sbjtRi}
			 , #{predctRi}
			 , #{objtRi}
			 , #{logDivMtcd}
			 , #{logStoreLoNm}
			 , #{logRegrId}
			 )

INSERT /* SQL_ID: RdfTripleLogMapper.insertRdfTripleLogList */
       INTO dtmeta.tb_rdf_triplelog
     ( rdf_triple_log_id
     , log_dt
     , sbjt_ri
     , predct_ri
     , objt_ri
     , log_div_mtcd
     , log_store_lo_nm
     , log_regr_id
     ) VALUES 

     ( 
       #{item.rdfTripleLogId}                         
     , current_timestamp
     , #{item.sbjtRi}
     , #{item.predctRi}
     , #{item.objtRi}
     , #{item.logDivMtcd}
     , #{item.logStoreLoNm} 
